create table if not exists public.season_calendar (key text not null, label text not null, starts date not null, hemi text);
create unique index if not exists season_calendar_u on public.season_calendar (key, starts, coalesce(hemi, ''));
alter table public.season_calendar enable row level security;
drop policy if exists "sc read" on public.season_calendar; create policy "sc read" on public.season_calendar for select using (true);
