create or replace function private.notify_seasons() returns void language sql security definer set search_path = '' as $$
  insert into public.notifications (user_id, kind, body, link)
  select m.user_id, 'tablero', 'En 7 días se activa el tema de temporada «' || c.label || '» en la página de ' || t.name || '. Revisa tu saludo y adorno.', jsonb_build_object('href', '/estudio/preferencias')
  from public.season_calendar c
  join public.teams t on (t.design->'seasons'->'auto') ? c.key and (c.hemi is null or c.hemi = coalesce(t.design->'seasons'->>'hemi', 'norte'))
  join public.team_members m on m.team_id = t.id and (m.role = 'owner' or coalesce((m.overrides->>'profile')::boolean, (select (r.perms->>'profile')::boolean from public.team_roles r where r.id = m.role_id), false))
  where c.starts = current_date + 7 $$;
select cron.unschedule('obi-season-notices') where exists (select 1 from cron.job where jobname = 'obi-season-notices');
select cron.schedule('obi-season-notices', '0 15 * * *', 'select private.notify_seasons()');